  const missing=engine.referencedIds().filter(id=>!engine.factoryIds.has(id)&&!engine.audio.has(id));
  if(missing.length)await engine.ensureSamples(missing);
  if(revision!==saveRevision)return;
  const portable=engine.getState({portable:'external'}),envelope={format:'batter-autosave',version:1,savedAt:Date.now(),state:portable};let localSaved=false,durableSaved=false;
