const waveformPeaks=new WeakMap();
function displayPeaks(audio,bins){let cached=waveformPeaks.get(audio);if(cached&&cached.bins===bins)return cached.values;const values=new Float32Array(bins),samplesPerBin=audio.length/bins;for(let i=0;i<bins;i++){let peak=0;const start=Math.floor(i*samplesPerBin),end=Math.max(start+1,Math.floor((i+1)*samplesPerBin));for(let j=start;j<end;j++)peak=Math.max(peak,Math.abs(audio[j]));values[i]=peak;}waveformPeaks.set(audio,{bins,values});return values;}
function drawWaveform(){const c=$('waveform'),r=c.getBoundingClientRect(),ratio=window.devicePixelRatio||1,w=Math.max(1,Math.round(r.width*ratio)),h=Math.round(r.height*ratio);if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.lineWidth=ratio;ctx.strokeStyle='#3a303b';for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(w*i/8,0);ctx.lineTo(w*i/8,h);ctx.stroke();}ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();const audio=waveAudio?.left;if(audio?.length){const bins=Math.ceil(w/ratio/2),peaks=displayPeaks(audio,bins);ctx.fillStyle='#b9a2ab';for(let i=0;i<bins;i++){const height=Math.max(ratio,peaks[i]*h*.7);ctx.fillRect(i*w/bins,h/2-height/2,Math.max(ratio,w/bins-ratio),height);}}else{ctx.fillStyle='#847382';ctx.font=10*ratio+'px monospace';ctx.textAlign='center';ctx.fillText('PREPARING INGREDIENT',w/2,h/2);}const l=lane(),a=l.start*w,b=l.end*w;ctx.fillStyle='#141218aa';ctx.fillRect(0,0,a,h);ctx.fillRect(b,0,w-b,h);ctx.fillStyle='#dfb277';ctx.fillRect(a,0,2*ratio,h);ctx.fillRect(b-2*ratio,0,2*ratio,h);for(const x of [a,b]){ctx.fillRect(x-4*ratio,5*ratio,8*ratio,16*ratio);}ctx.strokeStyle='#bba085';ctx.strokeRect(a+ratio,.5*ratio,Math.max(0,b-a-2*ratio),h-ratio);$('trimStartLabel').textContent='START '+(l.start*sampleDuration()).toFixed(3)+'s';$('trimEndLabel').textContent='END '+(l.end*sampleDuration()).toFixed(3)+'s';}
function bindWaveform(){const c=$('waveform');c.addEventListener('pointerdown',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width;waveDrag={edge:Math.abs(x-lane().start)<Math.abs(x-lane().end)?'start':'end',before:currentSnapshot()};c.setPointerCapture(e.pointerId);move(e);});function move(e){if(!waveDrag)return;const r=c.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));if(waveDrag.edge==='start')lane().start=Math.min(lane().end-.001,x);else lane().end=Math.max(lane().start+.001,x);drawWaveform();}c.addEventListener('pointermove',move);function end(){if(!waveDrag)return;remember(waveDrag.before);waveDrag=null;updateEngine();renderEditors(false);}c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end);c.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();transaction(()=>{const edge=e.shiftKey?'end':'start';if(e.key==='Home')lane().start=0;else if(e.key==='End')lane().end=1;else lane()[edge]=Math.max(0,Math.min(1,lane()[edge]+(e.key==='ArrowLeft'?-.005:.005)));},'edit');});new ResizeObserver(()=>drawWaveform()).observe(c);}
function registerRecoveredKit(source){
 if(!source?.kitId||!Array.isArray(source.lanes))return;
 engine.registerLibrary({samples:[],kits:[{id:source.kitId,name:source.kitName||'Recovered kit',restored:true,lanes:source.lanes.map(l=>({type:l.id,name:l.name,sampleId:l.sampleId,sampleIds:l.sampleIds.slice(),layerMode:l.layerMode}))}],bundles:[]});
}
async function useKit(id){
 const definition=kits().find(k=>k.id===id);await engine.setKit(id);
 if(definition?.restored){const restored=engine.getState();for(const l of restored.lanes){const saved=definition.lanes.find(v=>v.type===l.id);if(saved)l.layerMode=saved.layerMode;}engine.setState(restored);}
}
