function generateRecipe(name){const p=pattern();p.length=32;for(const sl of p.lanes){if(state.lanes[p.lanes.indexOf(sl)].protect)continue;sl.length=32;sl.steps=Array.from({length:64},(_,i)=>sl.steps[i]?.protect?sl.steps[i]:schema.step());}const place=(li,steps,velocity=.8,extra={})=>{const sl=p.lanes[li];if(state.lanes[p.lanes.indexOf(sl)].protect)return;for(const index of steps){const old=sl.steps[index];if(!old.protect)Object.assign(old,{on:true,velocity},extra);}};if(name==='empty'){p.length=16;p.lanes.forEach((sl,i)=>{if(!state.lanes[i].protect)sl.length=16;});return;}if(name==='straight'){p.length=16;p.lanes.forEach((sl,i)=>{if(!state.lanes[i].protect)sl.length=16;});place(0,[0,8],.9);place(1,[4,12],.88);place(3,[0,2,4,6,8,10,12,14],.55);place(4,[15],.5);return;}if(name==='halftime'){place(0,[0,7,16,22,25],.94);place(1,[8,24],.93);place(3,[0,3,6,10,12,16,19,22,26,28],.55);place(1,[14,23,30],.28,{micro:9});place(4,[15,31],.7);return;}if(name==='breakfast'){place(0,[0,6,10,16,19,26],.87);place(1,[4,12,20,28],.91);place(1,[3,7,11,15,23,27,30],.27,{micro:6});place(3,[0,2,3,6,8,10,11,14,16,18,19,22,24,26,27,30],.5);place(4,[7,23],.62);place(9,[31],.48,{ratchet:3});place(2,[13,29],.32,{probability:.7});return;}if(name==='splice'){place(0,[0,3,10,16,18,23,26],.9);place(1,[4,12,20,28],.84);place(1,[7,15,22,27,30],.32,{micro:-8,probability:.7});place(3,[0,2,5,6,8,10,13,14,16,18,21,22,24,26,29,30],.53);place(3,[11,31],.48,{ratchet:4,ratchetDecay:.35});place(7,[15,27],.45,{pitch:-3});place(10,[12,28],.28,{micro:10});return;}place(0,[0,3,9,16,19,26],.9);place(1,[4,12,20,28],.84);place(1,[2,7,11,15,18,23,27,30],.27,{micro:7,probability:.8});place(3,[0,2,3,6,8,10,11,14,16,18,19,22,24,26,27,30],.48);place(3,[15,31],.57,{ratchet:3,ratchetDecay:.32});place(4,[7,23],.55);place(8,[25],.4,{probability:.65,pitch:2});place(9,[29,31],.38,{ratchet:2});place(2,[5,17],.3,{probability:.62});place(11,[13,21,30],.35,{probability:.6,pitch:-4});}
