$('masterGain').onpointerdown=()=>rangeBefore=currentSnapshot();$('masterGain').oninput=()=>{if(!rangeBefore)rangeBefore=currentSnapshot();state.master.volume=10**(Number($('masterGain').value)/20);$('masterValue').textContent=db(state.master.volume);updateEngine();};$('masterGain').onchange=()=>{remember(rangeBefore);rangeBefore=null;};$('exportWavButton').onclick=()=>task('Rendering a complicated order…',async()=>{const cycles=Number($('exportCycles').value),bars=(schema.patternSpan(state,state.chainEnabled?'chain':'pattern')/4)*cycles;if(bars>64)throw new Error('This export exceeds 64 bars. Choose fewer cycles or a shorter chain.');const blob=await engine.renderWav({bars,scope:state.chainEnabled?'chain':'pattern',tailSeconds:2});download(blob,'BATTER-'+state.selectedPattern+'.wav');toast('Stereo WAV ready.');});$('exportPatternButton').onclick=()=>task('Packing the rhythm…',async()=>{if(window.MusicLabPatternInstrument?.capturePattern)jsonDownload(await window.MusicLabPatternInstrument.capturePattern({name:'BATTER '+state.selectedPattern}),'BATTER-pattern.json');else jsonDownload({format:'batter-pattern',version:1,tempo:state.tempo,swing:state.swing,pattern:pattern()},'BATTER-pattern.json');toast('Pattern downloaded.');});$('exportBundleButton').onclick=()=>task('Packing the samples…',async()=>{if(typeof engine.exportBundle==='function')jsonDownload(await engine.exportBundle(),'BATTER-samples.json');else{const project=await engine.getProject();jsonDownload({format:'kitchen-batter-library',version:1,samples:project.state.assets||[]},'BATTER-samples.json');}toast('Sample bundle downloaded.');});
$('helpButton').onclick=()=>$('helpDialog').showModal();$('closeHelpDialog').onclick=()=>$('helpDialog').close();for(const d of [$('helpDialog'),$('sampleDialog')])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea')||document.querySelector('dialog[open]'))return;if((e.code==='Space'||e.key==='Enter')&&e.target.closest('button,a,summary,[role="button"]'))return;if(e.code==='Space'){e.preventDefault();$('playButton').click();}else if(e.key==='Escape'){$('panicButton').click();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redoButton':'undoButton').click();}else if(!(e.ctrlKey||e.metaKey||e.altKey)){const index=['1','2','3','4','5','6','7','8','9','0','-','='].indexOf(e.key);if(index>=0){e.preventDefault();selectedLane=index;renderGrid();renderEditors();audition(index);}}});
