function animate(){if(!engine){requestAnimationFrame(animate);return;}const m=engine.getMeters(),idx=Number.isFinite(m.step)?Math.floor(m.step):-1;if(idx!==lastPosition||m.pattern!==lastPattern){lastPosition=idx;lastPattern=m.pattern;$('positionLabel').textContent=m.playing?'STEP '+String(idx+1).padStart(2,'0')+' / '+(state.patterns.find(p=>p.id===m.pattern)||pattern()).length:'STEP — / '+pattern().length;document.querySelectorAll('.step-cell.playing').forEach(el=>el.classList.remove('playing'));if(m.playing)document.querySelectorAll('.step-cell[data-step="'+idx+'"]').forEach(el=>el.classList.add('playing'));}const peak=Math.max(0,Number(m.peak)||0);$('meterFill').style.width=Math.min(100,Math.max(0,(20*Math.log10(Math.max(1e-6,peak))+48)/48*100))+'%';$('meterLabel').textContent=peak>1e-5?db(peak):'−∞ dB';requestAnimationFrame(animate);}
async function start(){try{$('playButton').disabled=true;$('audioStatus').innerHTML='<i></i>'+(window.MusicLabHost?'Opening the drum station…':'Opening the saved recipe…');if(location.protocol==='file:')$('labLink').href='https://calebhaines.github.io/sidequest-prototypes/music/';let saved=await restoreAutosave();try{engine=new window.BatterEngine(saved||undefined);if(saved&&engine.referencedIds().some(id=>!engine.metadata.has(id)))throw new Error('Some saved samples are unavailable.');}catch(_){engine=new window.BatterEngine();saved=null;toast('The saved recipe could not be restored. The starter kit is ready; open a downloaded backup.');}engine.onStatus=message=>toast(message);state=engine.getState();if(saved)registerRecoveredKit(state);if(!saved){const recipes=['offgrid','breakfast','splice','halftime','straight','breakfast','splice','offgrid'];for(let i=0;i<state.patterns.length;i++){state.selectedPattern=state.patterns[i].id;generateRecipe(recipes[i]);}state.selectedPattern='A';engine.setState(state);state=engine.getState();}renderKitChoices();bindEvents();renderAll();$('playButton').disabled=false;if(window.MusicLabHost)$('saveStatus').textContent='SAVE THE GALLEY PROJECT';else if(saved)$('saveStatus').textContent='RECIPE SAVED ON THIS DEVICE';animate();document.dispatchEvent(new CustomEvent('batter-ready'));}catch(err){error(err);$('audioStatus').textContent='Could not prepare the drums';}}
